    p=Path(folder); return sorted((x.resolve() for x in p.iterdir() if x.is_file() and x.suffix.lower() in ('.jpg','.jpeg','.png')),key=lambda x:x.name)
def dump(obj,path):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,indent=2)+'\n')
def main():
    ap=argparse.ArgumentParser(description=__doc__); sub=ap.add_subparsers(dest='cmd',required=True)
    p=sub.add_parser('group');p.add_argument('folder');p.add_argument('--scenes',type=int,default=4);p.add_argument('--out',required=True)
    p=sub.add_parser('target');p.add_argument('original');p.add_argument('--preset',choices=PRESETS,default='warm');p.add_argument('--recipe');p.add_argument('--out',required=True)
    p=sub.add_parser('fit');p.add_argument('original');p.add_argument('target');p.add_argument('--out',required=True);p.add_argument('--size',type=int,default=512)
    p=sub.add_parser('album');p.add_argument('groups');p.add_argument('--preset',choices=PRESETS,default='warm');p.add_argument('--recipe');p.add_argument('--out',required=True);p.add_argument('--size',type=int,default=512)
