    a=ap.parse_args()
    if a.cmd=='group':
        ps=files(a.folder)
        if not ps or a.scenes<1: raise ValueError('Need at least one photo and one scene')
        groups=cluster(ps,a.scenes); dump({'version':1,'method':'appearance baseline; manually review groups','groups':groups},a.out);print(f'{len(ps)} images in {len(groups)} groups: {a.out}')
    elif a.cmd=='target':
        v=vec(json.loads(Path(a.recipe).read_text()) if a.recipe else PRESETS[a.preset]);save_render(load(a.original),v,a.out);dump(recipe(v),str(a.out)+'.recipe.json');print(a.out)
    elif a.cmd=='fit':
