            except Exception as e: raise ValueError(f'Cannot convert ICC profile for {path}: {e}')
        else: im=im.convert('RGB')
        return np.asarray(im,dtype=np.float32)/255

def render(x,p):
    # Smooth per-pixel, ordered global light/color operations; no spatial movement.
    e,t,tint,c,sh,hi,s,r,b=p
    y=x*np.float32(2**e)*np.array([1+t+r,1+tint,1-t+b],dtype=np.float32)
    lum=np.sum(y*np.array([.2126,.7152,.0722],dtype=np.float32),axis=-1,keepdims=True)
    y=y+(lum*(1-np.clip(lum,0,1)))*(sh*(1-np.clip(lum,0,1))+hi*np.clip(lum,0,1))*2
    y=(y-.5)*(1+c)+.5
    lum=np.sum(y*np.array([.2126,.7152,.0722],dtype=np.float32),axis=-1,keepdims=True)
    return np.clip(lum+(y-lum)*(1+s),0,1)

def save(x,path,quality=95):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    Image.fromarray(np.uint8(np.clip(x*255+.5,0,255))).save(path,quality=quality,subsampling=0,icc_profile=ImageCms.ImageCmsProfile(ImageCms.createProfile('sRGB')).tobytes())

def save_render(x,p,path):
    # Bound temporary arrays for high-resolution JPEG exports.
    result=np.empty(x.shape,dtype=np.uint8)
    for start in range(0,x.shape[0],256):
        sl=slice(start,start+256)
        result[sl]=np.uint8(render(x[sl],p)*255+.5)
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    Image.fromarray(result).save(path,quality=95,subsampling=0,icc_profile=ImageCms.ImageCmsProfile(ImageCms.createProfile('sRGB')).tobytes())

def fit(a,b,iterations=45,seed=0):
    if a.shape!=b.shape: raise ValueError('Images have different dimensions; align/crop externally before fitting.')
    a=a.reshape(-1,3);b=b.reshape(-1,3)
    rng=np.random.default_rng(seed); idx=rng.choice(len(a),min(len(a),12000),replace=False); a=a[idx];b=b[idx]
    # Coordinate pattern search with step reduction, bounded, pixel reconstruction objective.
    p=np.zeros(len(NAMES)); steps=np.array([.18,.07,.06,.1,.09,.09,.12,.06,.06]); lo,hi=BOUNDS.T
    def loss(z):
        d=render(a,z)-b
        return float(np.mean(d*d)+1e-7*np.sum(z*z))
    best=loss(p); initial=best; calls=1
    for _ in range(iterations):
        improved=False
        for j in range(len(p)):
            cand=[]
            for direction in (-1,1):
                q=p.copy(); q[j]=np.clip(q[j]+direction*steps[j],lo[j],hi[j]); val=loss(q); calls+=1; cand.append((val,q))
            val,q=min(cand,key=lambda t:t[0])
            if val+1e-12<best: p=q;best=val;improved=True
        if not improved: steps*=.5
        if max(steps)<.0005: break
    return p,{'initial_mse':initial,'fit_mse':best,'rmse':math.sqrt(best),'evaluations':calls}

def features(x):
    # Features describe illumination, color and coarse composition, not semantic identity.
    y=x@np.array([.2126,.7152,.0722]); return np.array([np.mean(y),np.std(y),*np.quantile(y,[.1,.5,.9]),*x.mean((0,1)),*x.std((0,1))],dtype=float)

def cluster(paths,k):
    f=np.array([features(load(p,160)) for p in paths]); scale=np.std(f,axis=0); scale=np.maximum(scale,.04); z=(f-np.mean(f,axis=0))/scale
    k=min(k,len(paths)); centers=[int(np.argmin(np.linalg.norm(z-z.mean(0),axis=1)))]
    while len(centers)<k:
        dist=np.min(np.stack([np.sum((z-z[i])**2,axis=1) for i in centers]),axis=0); dist[centers]=-1; centers.append(int(np.argmax(dist)))
    c=z[centers].copy(); labels=np.zeros(len(paths),int)
    for _ in range(30):
        labels=np.argmin(((z[:,None,:]-c[None,:,:])**2).sum(axis=2),axis=1); new=c.copy()
        for i in range(k):
            if np.any(labels==i): new[i]=z[labels==i].mean(axis=0)
        if np.allclose(new,c): break
        c=new
    groups=[]
    for i in range(k):
        members=np.where(labels==i)[0]
        if not len(members): continue
        rep=members[np.argmin(((z[members]-c[i])**2).sum(axis=1))]
        groups.append({'id':f'scene-{i+1:02d}','representative':str(paths[rep]),'photos':[str(paths[j]) for j in members]})
    return groups

def files(folder):
    p=Path(folder); return sorted((x.resolve() for x in p.iterdir() if x.is_file() and x.suffix.lower() in ('.jpg','.jpeg','.png')),key=lambda x:x.name)
def dump(obj,path):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,indent=2)+'\n')
def main():
    ap=argparse.ArgumentParser(description=__doc__); sub=ap.add_subparsers(dest='cmd',required=True)
    p=sub.add_parser('group');p.add_argument('folder');p.add_argument('--scenes',type=int,default=4);p.add_argument('--out',required=True)
    p=sub.add_parser('target');p.add_argument('original');p.add_argument('--preset',choices=PRESETS,default='warm');p.add_argument('--recipe');p.add_argument('--out',required=True)
    p=sub.add_parser('fit');p.add_argument('original');p.add_argument('target');p.add_argument('--out',required=True);p.add_argument('--size',type=int,default=512)
    p=sub.add_parser('album');p.add_argument('groups');p.add_argument('--preset',choices=PRESETS,default='warm');p.add_argument('--recipe');p.add_argument('--out',required=True);p.add_argument('--size',type=int,default=512)
    p=sub.add_parser('evaluate');p.add_argument('originals');p.add_argument('edits');p.add_argument('--out',required=True);p.add_argument('--limit',type=int,default=10);p.add_argument('--size',type=int,default=512)
    a=ap.parse_args()
    if a.cmd=='group':
        ps=files(a.folder)
        if not ps or a.scenes<1: raise ValueError('Need at least one photo and one scene')
        groups=cluster(ps,a.scenes); dump({'version':1,'method':'appearance baseline; manually review groups','groups':groups},a.out);print(f'{len(ps)} images in {len(groups)} groups: {a.out}')
    elif a.cmd=='target':
        v=vec(json.loads(Path(a.recipe).read_text()) if a.recipe else PRESETS[a.preset]);save_render(load(a.original),v,a.out);dump(recipe(v),str(a.out)+'.recipe.json');print(a.out)
    elif a.cmd=='fit':
        x=load(a.original,a.size);y=load(a.target,a.size);v,metrics=fit(x,y);out=Path(a.out);out.mkdir(parents=True,exist_ok=True);save(render(x,v),out/'reconstruction.jpg');dump({'recipe':recipe(v),'metrics':metrics},out/'fit.json');print(json.dumps(metrics))
    elif a.cmd=='album':
        data=json.loads(Path(a.groups).read_text()); target=vec(json.loads(Path(a.recipe).read_text()) if a.recipe else PRESETS[a.preset]);out=Path(a.out); records=[]
        for g in data['groups']:
            rep=Path(g['representative']); x=load(rep,a.size); y=render(x,target); recovered,metrics=fit(x,y); scene=out/g['id'];save(y,scene/'target.jpg');save(render(x,recovered),scene/'reconstruction.jpg');dump({'known_recipe':recipe(target),'fitted_recipe':recipe(recovered),'metrics':metrics,'representative':str(rep)},scene/'fit.json')
            for path in g['photos']:
                src=Path(path); save_render(load(src),recovered,scene/'exports'/src.name)
            records.append({'scene':g['id'],'representative':str(rep),'photos':len(g['photos']),'metrics':metrics});print(g['id'],metrics,flush=True)
        dump({'scenes':records},out/'report.json')
    elif a.cmd=='evaluate':
        out=Path(a.out); rows=[]
        for src in files(a.originals):
            dst=Path(a.edits)/src.name
            if not dst.exists(): continue
            with Image.open(src) as x, Image.open(dst) as y:
                if ImageOps.exif_transpose(x).size != ImageOps.exif_transpose(y).size:
                    rows.append({'file':src.name,'status':'skipped: dimensions differ; alignment required'});continue
            x=load(src,a.size);y=load(dst,a.size);v,metrics=fit(x,y);save(render(x,v),out/'reconstructions'/src.name);rows.append({'file':src.name,'status':'fit; equal dimensions do not guarantee registration','recipe':recipe(v),'metrics':metrics})
            print(src.name,metrics['rmse'],flush=True)
            if sum(r['status'].startswith('fit;') for r in rows)>=a.limit:break
        dump({'results':rows},out/'report.json')
if __name__=='__main__': main()
# Morph reconstruction experiment

A local command-line research baseline: group photos by simple illumination/color features, produce an edited target with several deterministic controls, recover controls by bounded numerical fitting, and replay the recovered recipe on the scene. No API or model weights. The fitting model is numerical optimization, not a trained neural network. Scene assignments are an approximate starting point and can be edited in the JSON before rendering.

Requires Python 3, NumPy and Pillow (`python3 -m pip install numpy Pillow`). From this folder:

```bash
python3 morph.py group /Users/abhijitnambiar/Downloads/Morph/originals --scenes 4 --out groups.json
python3 morph.py album groups.json --preset warm --out album
python3 morph.py evaluate /Users/abhijitnambiar/Downloads/Morph/originals /Users/abhijitnambiar/Downloads/Morph/edits --limit 10 --out real-evaluation
```

Each scene contains a synthetic target, recovered preview, fit.json with known and fitted parameters, and full-resolution exports. Original files are never overwritten. The synthetic target is made by the same renderer as the fitter, so it measures inverse fitting under favorable conditions, not generalization to arbitrary editors. Full-size results require memory; processing is sequential.

Other commands: `target ORIGINAL --preset soft --out target.jpg` creates a target and a JSON recipe; `fit ORIGINAL TARGET --out fitted` fits aligned image pairs. Use `--recipe recipe.json` on target or album for a custom object with any of: exposure (-1.5 to 1.5 stops), temperature (-0.4 to 0.4), tint (-0.3 to 0.3), contrast (-0.6 to 0.6), shadows/highlights (-0.5 to 0.5), saturation (-0.8 to 0.8), red/blue (-0.3 to 0.3). Zero is neutral. Operations are ordered, global, and applied per pixel; they cannot move or synthesize content. Inspect the code for exact definitions. A preset is a fixed composite, not free-text prompt interpretation.

Real-pair evaluation skips different dimensions; equal dimensions do not establish alignment, so inspect the pairs for crop, rotation, or retouching. JPEG recompression and different editors can limit reconstruction. Reported fit errors are on the same sampled pixels used by the optimizer and are not held-out accuracy. Correlated controls may yield different slider values for visually similar images; judge both parameters and images. The grouping uses color and lighting statistics, not capture time or semantic scene recognition; review groups manually. This is a research prototype, not validated professional editing, a RAW workflow, or a guarantee of consistent album aesthetics. It does not yet implement per-photo normalization, human review, or a general prompt interpreter.

