        dist=np.min(np.stack([np.sum((z-z[i])**2,axis=1) for i in selected]),axis=0);dist[selected]=-1;selected.append(int(np.argmax(dist)))
    return [(candidates[i],ims[candidates[i]]) for i in selected]

