    p=argparse.ArgumentParser();p.add_argument('groups');p.add_argument('benchmark');p.add_argument('--out',required=True);p.add_argument('--anchors',type=int,default=3);p.add_argument('--size',type=int,default=256);a=p.parse_args();groups=morph.validate_groups(json.loads(Path(a.groups).read_text()));previous=json.loads(Path(a.benchmark).read_text());gmap={g['id']:g for g in groups};rows=[];cache={}
    for case in previous['cases']:
        g=gmap[case['scene']];held=[r['photo'] for r in case['heldout']['gamut']];key=(g['id'],tuple(held))
