        rows.append({'scene':g['id'],'case':case['case'],'anchors':[p for p,_ in anchors],'recipe':gamut_renderer.recipe(fitted),'metrics':metrics,'heldout':outcomes});print(g['id'],case['case'],len(anchors),'anchors',flush=True)
    held=[x for c in rows for x in c['heldout']];s=np.array([x['single_rmse'] for x in held]);j=np.array([x['joint_rmse'] for x in held]);morph.dump({'scope':'Synthetic targets from the same independent Pillow generator; additional anchors exclude held-out photos. Anchor selection and evaluation use the same unvalidated source album; no aesthetic review.','summary':{'cases':len(rows),'heldout':len(held),'single_mean_rmse':float(np.mean(s)),'joint_mean_rmse':float(np.mean(j)),'single_max_rmse':float(np.max(s)),'joint_max_rmse':float(np.max(j)),'joint_better':int(np.sum(j<s))},'cases':rows},a.out)
if __name__=='__main__':main()
