    """Independent synthetic editor, useful for cross-renderer reconstruction."""
    settings={'warm':(1.08,1.12,1.10,(1.07,1.00,.94)), 'cool':(1.05,1.10,.93,(.95,1.00,1.07)), 'soft':(1.07,.88,.90,(1.02,1.00,.98)), 'neutral':(1.,1.,1.,(1.,1.,1.))}
