    morph.dump({'scope':'Experimental face-relative reconstruction. Face boxes are unverified and local lighting affects surroundings.','scene':fit['scene'],'source_fit':str(Path(a.fit)),'mode':'preview' if a.preview_samples else 'scene','photos_without_detected_faces':sum(not r['faces'] for r in rows),'photos':rows},out/'report.json')


