const r=await tools.mcp__artifact_session__js({title:"Create research preview slides",timeout_ms:120000,code:`await artifactSession.run(async ({presentation,session}) => {
  presentation.theme.defaultFont='Arial';
  const base='/Users/abhijitnambiar/Documents/Codex/2026-10-27/i/outputs/';
  const data='/Users/abhijitnambiar/Downloads/Morph/originals/';
  const demo=base+'morph-demo-bundle/';
  const res=base+'morph-reconstruction/';
  const bg='#111B22', fg='#F4F2EA', muted='#B8C8C3', accent='#8EC2A8';
  function addSlide(){return presentation.slides.add({width:1280,height:720,background:{fill:bg}})}
  function txt(sl,text,x,y,w,h,size,color=fg,bold=false){
    const sh=sl.shapes.add({geometry:'textbox',position:{left:x,top:y,width:w,height:h},fill:'none',line:{fill:'none',width:0}});
    sh.text=text;sh.text.style={fontSize:size,typeface:'Arial',color,bold,verticalAlignment:'middle'};return sh;
  }
  function title(sl,heading,subtitle){txt(sl,heading,56,36,1168,68,42,fg,true);if(subtitle)txt(sl,subtitle,58,108,1160,45,22,muted);}
  function img(sl,path,x,y,w,h,alt){sl.images.add({path,alt,fit:'contain',position:{left:x,top:y,width:w,height:h}})}
  function note(sl,text){sl.speakerNotes.text=text}
  let s=addSlide();
  txt(s,'MORPH',58,68,410,44,24,accent,true);
  txt(s,'Scene edit\\nreconstruction',58,145,600,144,56,fg,true);
  txt(s,'Research preview',60,331,470,45,27,muted);
  img(s,demo+'originals/DSC_0901-1.jpg',716,98,510,510,'Sample scene photo');
  txt(s,'Prompt-guided color and lighting across a scene',60,573,590,62,22,fg);
  note(s,'Research preview. Source image: sample dataset, DSC_0901-1.jpg.');
  s=addSlide();title(s,'Pipeline overview','One representative edit becomes a reusable scene mapping');
  const columns=[
    ['01','Group','Propose scene groups and choose a representative'],
    ['02','Target','Create an edited target from the prompt'],
    ['03','Recover','Fit a deterministic color and lighting mapping'],
    ['04','Transfer','Apply the mapping to the other scene photos'],
    ['05','Normalize','Review photo, scene and album adjustments']
  ];
  columns.forEach((c,i)=>{let x=58+i*239;txt(s,c[0],x,210,180,40,22,accent,true);txt(s,c[1],x,257,218,42,29,fg,true);txt(s,c[2],x,320,210,130,21,muted)});
  txt(s,'Current prototype: local target generation, full-resolution JPEG output, and review controls.',58,596,1120,46,20,muted);
  note(s,'The scene grouping is a chronological heuristic. Normalization uses manual corrections and review-only metadata suggestions; it is not automatic.');
  s=addSlide();title(s,'Grouping photos into scenes','Capture time proposes groups; visual review can split or regroup them');
  img(s,data+'DSC_0958-15.jpg',60,193,500,334,'Lawn scene example');
  img(s,data+'DSC_0995-22.jpg',720,193,500,334,'Building scene example');
  txt(s,'LAWN SETTING',60,540,470,30,18,accent,true);txt(s,'BUILDING SETTING',720,540,470,30,18,accent,true);
  txt(s,'88 photos formed 9 proposed time-based groups. One group mixed these settings, so we tested a manual split.',60,606,1150,55,20,muted);
  note(s,'The supplied album contains 88 photos in 9 proposed chronological groups. Scene 02 was manually split into lawn and building for an illustrative experiment. This is not validated semantic clustering.');
  s=addSlide();title(s,'Prompt and target edit','A deterministic target is generated for the representative photo');
  txt(s,'“warm, slightly soft contrast and lift shadows”',60,160,1160,40,24,accent);
  txt(s,'ORIGINAL',60,216,540,28,18,muted,true);txt(s,'SYNTHETIC TARGET',680,216,540,28,18,muted,true);
  img(s,demo+'originals/DSC_0906-4.jpg',60,252,540,360,'Representative original');
  img(s,demo+'results/representative-target.jpg',680,252,540,360,'Deterministic target edit');
  txt(s,'The target combines tone and color operations on the original.',60,640,1160,30,19,muted);
  note(s,'The demo prompt uses the bounded offline vocabulary and the independent pillow-soft target engine. Source: morph-demo-bundle/results/representative-target.jpg.');
  s=addSlide();title(s,'Recovering the edit','Fit a mapping that reconstructs the target from the original');
  txt(s,'SYNTHETIC TARGET',60,170,540,28,18,muted,true);txt(s,'RECONSTRUCTION',680,170,540,28,18,muted,true);
  img(s,demo+'results/representative-target.jpg',60,207,540,360,'Target edit');
  img(s,demo+'results/representative-reconstruction.jpg',680,207,540,360,'Reconstruction from the learned deterministic mapping');
  txt(s,'Fit at a 320-pixel maximum dimension. Render the recovered mapping at the original dimensions.',60,603,1160,60,20,muted);
  note(s,'The reconstruction fits the gamut renderer to an independently implemented synthetic target. The recovered settings are a reproducible equivalent, not the target editor’s ground-truth parameters.');
  s=addSlide();title(s,'Transfer within the scene','Apply the saved mapping to a different photo');
  txt(s,'ORIGINAL',60,170,540,28,18,muted,true);txt(s,'RECOVERED EDIT APPLIED',680,170,540,28,18,muted,true);
  img(s,demo+'originals/DSC_0928-10.jpg',60,207,540,360,'Held-out scene original');
  img(s,demo+'results/DSC_0928-10.jpg',680,207,540,360,'Held-out scene image with the recovered mapping applied');
  txt(s,'The same scene mapping is applied to the other photo without refitting.',60,603,1160,40,20,muted);
  note(s,'Demo held-out photo DSC_0928-10. Its reduced-resolution pre-JPEG error to the synthetic per-photo target falls from 0.02719 to 0.00198. This does not measure subjective visual quality.');
  s=addSlide();title(s,'Normalization and review','Corrections can be applied at photo, scene, and album level');
  txt(s,'RECOVERED SCENE LOOK',60,171,540,28,18,muted,true);txt(s,'WITH ILLUSTRATIVE CORRECTIONS',680,171,540,28,18,muted,true);
  img(s,res+'face-real-album-preview/scene-01/exports/DSC_0904-2.jpg',60,207,540,360,'Photo with recovered scene look');
  img(s,res+'face-corrected-preview/scene-01/exports/DSC_0904-2.jpg',680,207,540,360,'Same photo with manual illustrative corrections');
  txt(s,'Exposure suggestions are review-only. Automatic normalization is not yet reliable.',60,603,1160,52,20,muted);
