const r=await tools.mcp__artifact_session__js({title:"Add side-by-side scene sets",timeout_ms:120000,code:`await artifactSession.run(async ({presentation})=>{
 const fs=await import('node:fs/promises');const root='/Users/abhijitnambiar/Documents/Codex/2026-10-27/i/work/slide-assets/';
 const before=presentation.slides.items.map(s=>'sl/'+s.id);const bg='#111B22',fg='#F4F2EA',muted='#B8C8C3',accent='#8EC2A8';
 function txt(s,text,x,y,w,h,size,color=fg,bold=false){const sh=s.shapes.add({geometry:'textbox',position:{left:x,top:y,width:w,height:h},fill:'none',line:{fill:'none',width:0}});sh.text=text;sh.text.style={fontSize:size,typeface:'Arial',color,bold,verticalAlignment:'middle'};}
 async function img(s,name,x,y,w,h,alt){const bytes=await fs.readFile(root+name);s.images.add({dataUrl:'data:image/jpeg;base64,'+bytes.toString('base64'),alt,fit:'contain',position:{left:x,top:y,width:w,height:h}});}
 let a=presentation.slides.add({width:1280,height:720,background:{fill:bg}});
 txt(a,'Scene set: three group photos',56,32,1168,65,42,fg,true);
 txt(a,'One fitted scene mapping is applied to each photo',58,100,1160,42,22,muted);
 txt(a,'ORIGINALS',60,148,300,30,18,accent,true);
 const names=['DSC_0901-1.jpg','DSC_0906-4.jpg','DSC_0928-10.jpg'];
 for(let i=0;i<3;i++)await img(a,'scene-01-original-'+names[i]+'.jpg',60+i*400,181,360,215,'Original '+names[i]);
 txt(a,'SCENE EDIT APPLIED',60,410,400,30,18,accent,true);
 for(let i=0;i<3;i++)await img(a,'scene-01-edited-'+names[i]+'.jpg',60+i*400,442,360,215,'Edited '+names[i]);
 a.speakerNotes.text='Three photos from scene 01 of the full-album face-aware run. All outputs use the same fitted mapping and per-photo detected face boxes. Top row originals, bottom row edits. The sample includes the representative and two other scene photos.';
 let b=presentation.slides.add({width:1280,height:720,background:{fill:bg}});
 txt(b,'Scene set: two portraits',56,32,1168,65,42,fg,true);
 txt(b,'Two photos share the mapping recovered for their scene',58,100,1160,42,22,muted);
 const portraits=['DSC_1280-55.jpg','DSC_1284-57.jpg'];
 for(let i=0;i<2;i++){
   const x=60+i*620;
   txt(b,'ORIGINAL',x,175,255,30,18,accent,true);txt(b,'EDITED',x+290,175,255,30,18,accent,true);
   await img(b,'scene-06-original-'+portraits[i]+'.jpg',x,214,255,370,'Original '+portraits[i]);
   await img(b,'scene-06-edited-'+portraits[i]+'.jpg',x+290,214,255,370,'Edited '+portraits[i]);
 }
 txt(b,'Each pair uses the same scene fit. Face regions follow detections in each photo.',60,626,1155,38,20,muted);
 b.speakerNotes.text='These two photos are from scene 06 and are not the fitted representative, DSC_1286-58.jpg. Their edits use the same recovered mapping with each photo’s own detected face boxes. The source album and original files are preserved.';
 presentation.slides.reorder([...before.slice(0,6),'sl/'+a.id,'sl/'+b.id,...before.slice(6)]);
 nodeRepl.write({slideCount:presentation.slides.items.length});
},{artifactType:'presentation',artifactRef:'artifact_JLHbSfxbNHQltjlmtn1Mb-UVTpTHXr4N'});`});text(r)

